  generateSelfSignedCertificate: generateSimpleSelfSignedCert,

  // Constants
  TLS_ALGORITHM,
  TLS_KEY_LENGTH,
  TLS_IV_LENGTH,
  TLS_AUTH_TAG_LENGTH
};

